sys_ui_action.script:
// Helper: update a system property value securely
function updateSysProperty(propertyName, value) {
    var gr = new GlideRecordSecure('sys_properties');
    gr.addQuery('name', propertyName);
    gr.query();
    if (gr.next()) {
        gr.value = value;
        gr.update();
    }
}

// Logging helper for the application log table
function logTestConnectionEvent(logLevel, message) {
    var log = new GlideRecord('x_1784056_sixscape_log');
    log.initialize();
    log.log_level = logLevel;
    log.script = "Test Connection";
    log.application = "Sixscape IDC";
    log.message = message;
    log.insert();
}

(function() {
    try {
        // --- Update system properties securely ---
        updateSysProperty("x_1784056_sixscape.Application ID", current.application_id);
        updateSysProperty("x_1784056_sixscape.End Point", current.end_point);
        updateSysProperty("x_1784056_sixscape.Application Secret", current.application_secret.getDecryptedValue());
        updateSysProperty("x_1784056_sixscape.Mid Server Name", current.mid_server);
        updateSysProperty("x_1784056_sixscape.Key Manager Pin", current.key_manager_pin.getDecryptedValue());

        // --- Test connection ---
        var test = new GetToken();
        var response = test.TestConnection();

        if (!response || response.length < 2) {
            throw new Error('Invalid response from TestConnection.');
        }
        var status = response[0];
        var responseBody = response[1];

        if (status === 200) {
            current.status = "Connection from ServiceNow to IDcentral is Successful";
            logTestConnectionEvent("Info", current.status);
        } else if (status === 0) {
            current.status = "Please check if the MID Server is up and running.";
            logTestConnectionEvent("Warning", current.status);
        } else {
            try {
                var parsedResponse = JSON.parse(responseBody);
                current.status = parsedResponse.title || 
                    "Unable to connect from ServiceNow to IDcentral, please check the configurations.";
                logTestConnectionEvent("Error", current.status);
            } catch (parseError) {
                current.status = "Unable to connect from ServiceNow to IDcentral. Error: " + responseBody;
                logTestConnectionEvent("Error", 'Error parsing response body: ' + parseError.message);
            }
        }
    } catch (ex) {
        logTestConnectionEvent("Error", "An unexpected error occurred: " + ex.message);
        gs.addErrorMessage('An unexpected error occurred: ' + ex.message);
    } finally {
        current.update();
        action.setRedirectURL(current.getLink());
    }
})();
